import {
    effect,
    inject,
    Injectable,
    Injector,
    signal,
    untracked,
} from '@angular/core';
import { toSignal } from '@angular/core/rxjs-interop';
import { Point, ViewerFeature } from '@placeos/common';
import { showMetadata } from '@placeos/ts-client';

import {
    AsyncHandler,
    firstValueWhere,
    HashMap,
    i18n,
    OrganisationService,
    SettingsService,
} from '@placeos/common';

import {
    MapCanvasComponent,
    Polygon,
} from 'libs/components/src/lib/map-canvas.component';
import { ExploreIconComponent } from './explore-icon.component';
import { ExploreSensorInfoComponent } from './explore-sensor-info.component';
import { DEFAULT_COLOURS } from './explore-spaces.service';
import { ExploreStateService } from './explore-state.service';

export interface ZoneData {
    /** ID of the zone */
    map_id?: string;
    /** ID of the zone */
    area_id: string;
    /** Max occupancy allowed in zone */
    capacity: number;
    /** Number of devices in the zone */
    count: number;
    /** Key in the ZoneData to use for people count */
    area_count_key: string;
    /** Average temperature from the sensors in the zone */
    temperature: number;
    /** Average humidity from the sensors in the zone */
    humidity: number;
    people_count: number;
    people_count_sum: number;
    queue_size: number;
    counter: number;
    at_location?: number;
}

@Injectable()
export class ExploreZonesService extends AsyncHandler {
    private _state = inject(ExploreStateService);
    private _org = inject(OrganisationService);
    private _settings = inject(SettingsService);
    private _injector = inject(Injector);

    private _org_initialised = toSignal(this._org.initialised, {
        initialValue: false,
    });
    private _building = toSignal(this._org.active_building, {
        initialValue: null,
    });

    private _area_list: string[] = [];
    private _statuses: HashMap<string> = {};
    private _count_key: HashMap<string> = {};
    private _location: HashMap<Point> = {};
    private _label_location: HashMap<Point> = {};
    private _capacity: HashMap<number> = {};
    private _draw: HashMap<boolean> = {};
    private _points: HashMap<[number, number][]> = {};
    private _features: ViewerFeature[] = [];
    private _polygons = signal<Polygon[]>([]);

    private _area_data = signal<{ value?: any[] }>(null);
    private _zone_data = signal<{ value?: any[] }>(null);

    constructor() {
        super();
        // Bind to the area management state of the active level
        effect(() => {
            const bld = this._building();
            const lvl = this._state.level();
            const { is_public } = this._state.options();
            if (!bld || !lvl || is_public) return;
            untracked(() => this._bindToLevel(lvl.id));
        });
        // Process zone data from the level's bindings
        effect(() => {
            const areas = this._area_data();
            const zone = this._zone_data();
            this.timeout(
                'parse_data',
                () =>
                    this.parseData([
                        ...(areas?.value || []),
                        ...(zone?.value || []).filter(
                            (_) => _.location === 'area',
                        ),
                    ]),
                100,
            );
        });
        this.init();
    }

    public async init() {
        await firstValueWhere(
            this._org_initialised,
            (_) => !!_,
            this._injector,
        );
        const zone_metadata = await Promise.all(
            this._org.levels.map((bld) =>
                showMetadata(bld.id, 'map_regions').catch(() => null),
            ),
        );
        this._area_list = [];
        for (const zone of zone_metadata) {
            const areas = (zone?.details as any)?.areas;
            if (!areas) continue;
            for (const area of areas) {
                const {
                    capacity,
                    hide_label,
                    label_location,
                    draw_polygon,
                    area_count_key,
                } = area.properties || {};
                const { coordinates } = area.geometry || {};
                this._capacity[area.id] = capacity || 100;
                this._count_key[area.id] = area_count_key || '';
                this._location[area.id] = coordinates?.length
                    ? getCenterPoint(coordinates)
                    : null;
                this._label_location[area.id] =
                    hide_label === false
                        ? label_location || this._location[area.id]
                        : null;
                this._draw[area.id] =
                    !!draw_polygon ||
                    this._settings.get('app.explore.use_zone_polygons');
                this._points[area.id] = coordinates || [];
                this._area_list.push(area.map_id || area.id);
            }
        }
        this._state.setFeatures('zones-canvas', [
            {
                track_id: 'zones-canvas',
                location: { x: 0.5, y: 0.5 },
                content: MapCanvasComponent,
                data: {
                    polygons: this._polygons.asReadonly(),
                    draw_points: false,
                    draw_labels: false,
                },
            },
        ]);
        this.updateStatus();
    }

    private _bindToLevel(zone_id: string) {
        this._statuses = {};
        const mod = this._org.module('area_management', 'AreaManagement');
        if (!mod) return;
        const bind_areas = mod.variable(`${zone_id}:areas`);
        const bind_zone = mod.variable(`${zone_id}`);
        this.subscription(
            'binding',
            bind_areas.bindThenSubscribe((d) => this._area_data.set(d)),
        );
        this.subscription(
            'zone-binding',
            bind_zone.bindThenSubscribe((d) => this._zone_data.set(d)),
        );
    }

    public parseData(value: ZoneData[] = []) {
        const labels = [];
        const features = [];
        const temp_unit = this._settings.get('app.use_imperial_units')
            ? 'F'
            : 'C';
        for (const zone of value) {
            const id = zone.map_id || zone.area_id;
            // if (!this._area_list.includes(id)) continue;
            const capacity = zone.capacity || this._capacity[id] || 100;
            const count =
                zone[
                    this._count_key[id] ||
                        this._settings.get('app.explore.area_count_key') ||
                        'count'
                ] || 0;
            const filled = count / capacity;
            this._statuses[id] = zone.at_location
                ? 'busy'
                : filled < 0.4
                  ? 'free'
                  : filled < 0.75
                    ? 'pending'
                    : 'busy';
            if (!this._location[id]) continue;
            let content = '';
            if (zone.count) {
                content +=
                    i18n('EXPLORE.DEVICE_COUNT', { count: zone.count }) + '\n';
            }
            if (zone.temperature)
                content += i18n('EXPLORE.SENSORS_TEMP', {
                    value: `${zone.temperature} °${temp_unit}\n`,
                });
            if (zone.people_count > 0)
                content += i18n('EXPLORE.SENSORS_PEOPLE', {
                    count: `${zone.people_count_sum}\n`,
                });
            if (zone.humidity)
                content += i18n('EXPLORE.SENSORS_HUMIDITY', {
                    value: `${zone.humidity}\n`,
                });
            if (zone.queue_size)
                content += i18n('EXPLORE.SENSORS_QUEUE', {
                    value: `${zone.queue_size}\n`,
                });
            if (zone.counter)
                content += i18n('EXPLORE.SENSORS_COUNT', {
                    value: `${zone.counter}\n`,
                });
            if (
                this._label_location[id] &&
                !this._settings.get('app.explore.show_zone_labels')
            ) {
                labels.push({
                    location: this._label_location[id],
                    content,
                    z_index: 100,
                });
            }
            if (
                this._settings.get('app.explore.show_zone_sensor_info') &&
                (zone.temperature || zone.humidity)
            ) {
                features.push({
                    track_id: `sensors:${id}`,
                    location: this._location[id],
                    content: ExploreSensorInfoComponent,
                    data: {
                        id,
                        temp: zone.temperature || 10,
                        temp_unit,
                        humidity: zone.humidity || 10,
                    },
                    z_index: 98,
                });
            }
        }
        this._features = features;
        this._state.setLabels('zones', labels);
        this.updateStatus();
    }

    private updateStatus() {
        const style_map = {};
        const features = [];
        const colours = this._settings.get('app.explore.colors') || {};
        const polygons = [];
        for (const zone_id in this._statuses) {
            const colour =
                colours[`zone-${this._statuses[zone_id]}`] ||
                colours[`${this._statuses[zone_id]}`] ||
                DEFAULT_COLOURS[`${this._statuses[zone_id]}`];
            if (this._draw[zone_id]) {
                polygons.push({
                    name: zone_id,
                    points: this._points[zone_id],
                    color: colour,
                } as Polygon);
            } else {
                if (
                    this._state.has('style', zone_id, ['zones', 'zones-styles'])
                ) {
                    features.push({
                        location: zone_id,
                        content: ExploreIconComponent,
                        data: {
                            icon: { content: 'pin_drop' },
                        },
                        full_size: true,
                        z_index: 98,
                    } as ViewerFeature);
                } else {
                    style_map[`#${zone_id}`] = {
                        fill: colour,
                        opacity: 0.6,
                    };
                }
            }
        }
        this._polygons.set(polygons);
        this._state.setFeatures('zones', [...features, ...this._features]);
        this._state.setStyles('zones-styles', style_map);
    }
}

function getCenterPoint(points: [number, number][]) {
    const diff: HashMap<number> = (points || []).reduce(
        (m, [x, y]) => ({
            x_min: x < m.x_min ? x : m.x_min,
            x_max: x > m.x_max ? x : m.x_max,
            y_min: y < m.y_min ? y : m.y_min,
            y_max: y > m.y_max ? y : m.y_max,
        }),
        {
            x_min: 100,
            x_max: -100,
            y_min: 100,
            y_max: -100,
        },
    );
    return {
        x: diff.x_min + (diff.x_max - diff.x_min) / 2,
        y: diff.y_min + (diff.y_max - diff.y_min) / 2,
    };
}
